def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]
    last_me = my[-1]
    last_op = op[-1]

    if last_op == 'D':
        # Retaliate immediately, but don't get stuck in long mutual defection
        # if opponent has been mostly cooperative overall.
        opp_def = op.count('D')
        if opp_def <= 1:
            # first defection: punish once, then forgive
            return 'D'
        recent_op = op[-4:]
        recent_def = recent_op.count('D')
        if recent_def >= 3:
            return 'D'
        if last_me == 'D':
            # We already punished; return toward cooperation
            if rng.random() < 0.8:
                return 'C'
        return 'D'

    # Opponent cooperated last round.
    if n >= 5:
        recent = op[-5:]
        recent_def = recent.count('D')
        if recent_def == 0:
            # sustained cooperation: mostly cooperate, rare late probe
            if n >= 92 and rng.random() < 0.15:
                return 'D'
            return 'C'
        if recent_def == 1:
            # one recent defection: stay cooperative to recover
            return 'C'
        if recent_def >= 3:
            # recurring defections: press advantage carefully
            if rng.random() < 0.4:
                return 'D'
            return 'C'

    if n >= 3:
        opp_def = op.count('D')
        if opp_def * 2 > n:
            # opponent is defecting more often than not: exploit
            if rng.random() < 0.5:
                return 'D'

    return 'C'
